package nenkin;
import javax.servlet.http.HttpServletRequest;import javax.servlet.http.HttpServletResponse;import nenkin.bean.ReportViewBean;import nenkin.service.PensionRepository;
public final class ReportPreviewAction extends NenkinBaseAction { public String perform(HttpServletRequest request,HttpServletResponse response){if(!requireStaff(request))return STAFF_JSP;ReportViewBean bean=new ReportViewBean();bean.setUseBranchRange(isChecked(request,"USE_BRANCH_RANGE"));bean.setBranchFrom(trim(request.getParameter("BRANCH_FROM")));bean.setBranchTo(trim(request.getParameter("BRANCH_TO")));bean.setSortType(integerOrDefault(request.getParameter("SORT_TYPE"),1));Integer from=integerOrNull(bean.getBranchFrom()),to=integerOrNull(bean.getBranchTo());if(bean.isUseBranchRange()&&from==null){bean.setMessage("店番を正しく入力して下さい！");}else if(bean.isUseBranchRange()&&to!=null&&from.intValue()>to.intValue()){bean.setMessage("店番自は店番至以下を入力してください。");}else{bean.setRows(PensionRepository.getInstance().search(bean.isUseBranchRange()?from:null,bean.isUseBranchRange()?to:null,bean.getSortType()));bean.setPreview(true);}setViewBean(request.getSession(),bean);return REPORT_JSP;} }
